"C:\\Program Files\\PowerShell\\7\\pwsh.exe" -NoProfile -Command '$ErrorActionPreference='"'Stop'
if((Get-Location).Path-ne'D:\\EliteSync-v10'){throw 'CWD'}
if((git branch --show-current)-ne'main'-or(git rev-parse HEAD)-ne'cf8bfaa4a03b8c9a682105617b185141904413be'){throw 'GIT'}
"'$s=Get-Content -LiteralPath '"'EVIDENCE/APP-M5-79-SINGLE-SOURCE-BOOTSTRAP-BEHAVIOR/workspace-before.json' -Raw|ConvertFrom-Json
"'$now=@(git -c core.quotepath=false status --porcelain=v1|ForEach-Object{$_.Substring(3)})
$missing=@($s.Paths|Where-Object{$_ -notin $now})
if($s.Count-ne236-or$s.Paths.Count-ne236-or$missing.Count-ne0){throw '"'SNAPSHOT'}
if(Test-Path -LiteralPath 'EVIDENCE/APP-M5-79-SINGLE-SOURCE-BOOTSTRAP-BEHAVIOR/behavior-contract.md'){throw 'TARGET_EXISTS'}
"'$f=Get-Item -LiteralPath '"'apps/android_synthetic_demo/tools/aar_entry_materials.py'
if("'$f-isnot[IO.FileInfo]-or($f.Attributes-band[IO.FileAttributes]::ReparsePoint)-ne0){throw '"'FILE'}
"'$d=$f.Directory
while($null-ne$d){if($d-isnot[IO.DirectoryInfo]-or($d.Attributes-band[IO.FileAttributes]::ReparsePoint)-ne0){throw '"'ANCESTOR'};"'$d=$d.Parent}
if($f.Length-ne20338){throw '"'SIZE'}
"'$b=[IO.File]::ReadAllBytes($f.FullName)
$sha=[Security.Cryptography.SHA256]::Create()
try{$h=[BitConverter]::ToString($sha.ComputeHash($b)).Replace('"'-','')}finally{"'$sha.Dispose()}
if($h-ne'"'B324943D7CC88EB714DD19450E0E9A2853609580C3A6F9FBFACAC0DA11D04DD7'){throw 'HASH'}
"'$utf=[Text.UTF8Encoding]::new($false,$true)
$t=$utf.GetString($b)
$parts=[Collections.Generic.List[string]]::new()
$parts.Add("A_OK branch=main HEAD=cf8bfaa4a03b8c9a682105617b185141904413be old=236 missing=0 status=$($now.Count) sourceReads=1 targetAbsent=true sourceBytes=$($b.Length) hash=$h ordinaryFullAncestors=true strictUTF8=true")
$lines=$t.Split([char]10)
for($j=0;$j-lt$lines.Length;$j++){if(($j-ge32-and$j-le109)-or$j-ge169){$parts.Add(('"'{0}: {1}'-f("'$j+1),$lines[$j].TrimEnd([char]13)))}}
$out=[string]::Join([Environment]::NewLine,$parts)
$receipt="BODY_BYTES=$($utf.GetByteCount($out)) BODY_CHARS=$($out.Length) aggregateLimits=12288/14000"
$out=$receipt+[Environment]::NewLine+$out
if($utf.GetByteCount($out)-gt12288-or$out.Length-gt14000){throw '"'OUTPUT_LIMIT'}
[Console]::WriteLine("'$out)'
